    conscious,
    pause,
    oneReel,
    over,
  ];

  /// Inside the mode card, between its edge and the chip.
  static const double spaceInset = 8;

  /// Between blocker tiles, and between the tiles and the rules row.
  static const double spaceGap = 14;

  /// Padding inside tiles.
  static const double spaceCard = 16;

  /// Screen side margins (390pt screen).
  static const double spaceGutter = 20;

  /// Above a section title.
  static const double spaceSection = 32;

  /// App icon squircles in a tile's icon stack (site icons are round).
  static const double radiusIcon = 8;

  /// Selected-mode chip: radius-card minus the 8px inset.
  static const double radiusChip = 20;

  /// Blocker rules row.
  static const double radiusRow = 22;

  /// Blocker tiles and the mode card.
  static const double radiusCard = 28;

  /// Tab bar and the slide track.
  static const double radiusBar = 32;

  /// Confirm sheet.
  static const double radiusSheet = 40;

  /// Pills, buttons, the tab lens, status dots.
  static const double radiusPill = 999;

  /// Glass controls: backdrop blur.
  static const double glassBlur = 22;

  /// Glass controls: backdrop saturation.
  static const double glassSaturate = 1.8;

  /// Frosted panel: backdrop blur.
  static const double panelBlur = 20;

  /// Frosted panel: backdrop saturation.
  static const double panelSaturate = 1.6;

  /// Confirm sheet: backdrop blur.
  static const double sheetBlur = 30;

  /// Confirm sheet: backdrop saturation.
  static const double sheetSaturate = 1.7;

  /// Sheet scrim: backdrop blur.
  static const double scrimBlur = 8;

  /// Sheet scrim: backdrop saturation.
  static const double scrimSaturate = 1.2;

  /// Light coloured text mixes the accent toward this ink (--accent-text: color-mix(in srgb, accent 60%, #0b1020)).
  static const Color accentTextInk = Color(0xFF0B1020);

  /// How far Light coloured text mixes toward accent-text-ink (the ink's share of --accent-text).
  static const double accentTextMix = 0.4;

  /// Light ring arc middle stop: the accent mixed this far toward its deep stop (--arc-50).
  static const double arcMidMix = 0.5;

  /// Ring centre disc wash: the accent at this alpha (.dx-disc::before).
  static const double discWash = 0.06;

  /// Hue of the blue 3D mode icons; hue-rotate(accent hue - 214deg) turns them to the accent.
  static const double iconBaseHue = 214;

  /// Selected mode icon: saturate(1.15).
  static const double iconSaturateOn = 1.15;

  /// Idle mode icon: saturate(.7).
  static const double iconSaturateOff = 0.7;

  /// Idle mode icon opacity.
  static const double iconOpacityOff = 0.8;

  /// Quick-pick card and the tab lens (Compact Guide card-sm).
  static const double radiusCardSm = 26;

  /// Sheet padding, sides and bottom (Compact Guide sheet side).
  static const double spaceSheetSide = 22;

  /// Screen top to the tab header row (Compact Guide header top), safe area included.
  static const double spaceHeaderTop = 54;
}

/// The confirm sheet's tones: the slide fill [a] → [b] (at 55 %) → [c], the
/// text on it ([ink]) and the glyphs on the knob ([knob]).
enum ConfirmTone {
  /// Confirm sheet, caution tone (unblocking).
  caution(
    a: Color(0xFFFFC062),
    b: Color(0xFFFF9A3D),
    c: Color(0xFFFF6F4E),
    ink: Color(0xFF2B1404),
    knob: Color(0xFFC25E00),
  ),

  /// Critical tone (turning protection off, deleting).
  critical(
    a: Color(0xFFFF8FA3),
    b: Color(0xFFFF5C7A),
    c: Color(0xFFE8366A),
    ink: Color(0xFF2E0814),
    knob: Color(0xFFC8234F),
  ),

  /// Neutral tone (safe changes).
  neutral(
    a: Color(0xFF8FD3FF),
    b: Color(0xFF6AA8FF),
    c: Color(0xFF8B7CFF),
    ink: Color(0xFF0A1430),
    knob: Color(0xFF3767DB),
  );

  const ConfirmTone({
    required this.a,
    required this.b,
    required this.c,
    required this.ink,
    required this.knob,
  });

  final Color a;
  final Color b;
  final Color c;
  final Color ink;
  final Color knob;
}

